import React, { useState, useEffect, useRef } from "react";
import "./App.css";
import botIcon from "./bot-icon.png"; // Add a chatbot logo in your project folder

const App = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState("");
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendMessage = () => {
    if (input.trim() === "") return;

    setMessages([...messages, { text: input, type: "user" }]);
    setInput("");

    // Simulate AI response
    setTimeout(() => {
      setMessages((prevMessages) => [
        ...prevMessages,
        { text: "AI Response: " + input, type: "bot" },
      ]);
    }, 1000);
  };

  return (
    <div className="app-container">
      {/* Header */}
      <header className="header">
        <h1>🤖 AI Tutor</h1>
      </header>

      {/* Chat Box */}
      <div className="chatbox">
        <div className="messages">
          {messages.map((msg, index) => (
            <div key={index} className={`message-container ${msg.type}`}>
              {msg.type === "bot" && <img src={botIcon} alt="Bot" className="bot-icon" />}
              <div className={`message ${msg.type}`}>
                <p>{msg.text}</p>
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="input-area">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask me anything..."
          />
          <button onClick={handleSendMessage}>➤</button>
        </div>
      </div>

      {/* Footer */}
      <footer className="footer">
        <p>&copy; 2025 AI Tutor | Built with ❤️</p>
      </footer>
    </div>
  );
};

export default App;
